import { useState, useEffect } from "react";
import ChromeMockup from "./ChromeMockup";
import { detectPlatform } from "./utils";

export default function ScreenCanvas({ manifest }) {
    const [platform, setPlatform] = useState("win");
    const [stack, setStack] = useState([]);
    const [active, setActive] = useState(null);

    useEffect(() => {
        setPlatform(detectPlatform());
    }, []);

    // initialize stack on first load
    useEffect(() => {
        if (manifest.length > 0 && stack.length === 0) {
            setStack(manifest.map((_, i) => i));
        }
    }, [manifest]);

    const bringToFront = (clickedIndex) => {
        // setActive(clickedIndex === active ? null : clickedIndex);
        setActive(clickedIndex);
        setStack((prevStack) => {
            const newStack = prevStack.filter((i) => i !== clickedIndex);
            newStack.push(clickedIndex);
            return newStack;
        });
    };

    return (
        <>
            {manifest.length > 0 &&
                manifest.map((item, index) => {
                    const zIndex = stack.indexOf(index); // top = highest

                    return (
                        <ChromeMockup
                            key={index}
                            content={{
                                imgUrl: item.imgUrl,
                                pageUrl: item.pageUrl,
                                dims: item.dims || { width: 800, height: 600 },
                                title: item.title || "Mockup Content",
                            }}
                            position={item.position}
                            platform={platform}
                            mode={"light"}
                            active={active === index}
                            zIndex={zIndex}
                            onClick={() => bringToFront(index)}
                        />
                    );
                })}
            {/* <div
                style={{
                    position: "absolute",
                    top: 0,
                    left: 0,
                    width: "100%",
                    height: "100%",
                    zIndex: 100,
                    backgroundColor: "#eeeeee",
                    opacity: active == null ? 0 : 0.1,
                    transition: "opacity .3s",
                    pointerEvents: "none",
                }}
            ></div> */}
        </>
    );
}
