import { Box, Typography, Paper } from "@mui/material";
import Draggable from "react-draggable";

import NavigationBar from "./mockup/NavigationBar";
import ControlBar from "./mockup/ControlBar";

export default function ChromeMockup({
    content = {
        imgUrl: null,
        pageUrl: null,
        dims: { width: 800, height: 600 },
    },
    platform = "mac",
    position = { top: 0, left: 0 },
    mode = "light",
    active = false,
    onClick = () => {},
    imgBackground = true,
    zIndex = 1,
}) {
    const colors = {
        light: {
            main: imgBackground ? "transparent" : "rgba(224,224,224)",
            btns: "rgba(100,100,100)",
            brd: "rgba(192,192,192)",
        },
        dark: {
            main: "rgba(31,31,31)",
            btns: "rgba(150,150,150)",
            brd: "rgba(63,63,63)",
        },
    };

    const backImgS = {
        backgroundImage: content.imgUrl ? `url(${content.imgUrl})` : "none",
        backgroundSize: "300%",
        backgroundPosition: "center",
    };

    return (
        <Draggable
            handle=".drag-handle"
            bounds="#root"
            onMouseDown={(e) => {
                // Prevent click events from propagating to the draggable
                e.stopPropagation();
                onClick();
            }}
        >
            <Paper
                elevation={active ? 10 : 1}
                sx={{
                    minWidth: "600px",
                    maxWidth: "600px",
                    scale: active ? 1 : 0.8,
                    transformOrigin: "center",
                    borderRadius: 2,
                    overflow: "hidden",
                    backgroundColor: colors[mode].main,
                    border: `1px solid ${colors[mode].brd}`,
                    position: "absolute",
                    zIndex: active ? 1000 : zIndex,
                    ...position,
                    ...(imgBackground ? backImgS : {}),
                    transition: "scale 0.3s ease-in-out",
                }}
                // onMouseDown={onClick}
                className="browser"
            >
                {/* Header */}
                <Box
                    sx={{ backdropFilter: "blur(50px)" }}
                    className="drag-handle"
                >
                    <ControlBar
                        platform={platform}
                        colors={colors[mode]}
                    />

                    <NavigationBar
                        content={content}
                        colors={colors[mode]}
                    />
                </Box>

                <Box
                    sx={{
                        backgroundColor: "#fff",
                        height: "100%",
                        display: "flex",
                        justifyContent: "center",
                        alignItems: "center",
                        cursor: "pointer",
                    }}
                    className={!active ? "drag-handle" : ""}
                    // onMouseDown={() => {
                    //     if (content.pageUrl && !active) {
                    //         window.open(content.pageUrl, "_blank");
                    //     }
                    // }}
                >
                    {content.imgUrl ? (
                        <img
                            src={content.imgUrl}
                            alt={content.title}
                            draggable={false}
                            style={{
                                maxWidth: "100%",
                                maxHeight: "100%",
                                objectFit: "contain",
                            }}
                        />
                    ) : (
                        <Typography
                            variant="body2"
                            color="text.secondary"
                        >
                            No image loaded
                        </Typography>
                    )}
                </Box>
            </Paper>
        </Draggable>
    );
}
